INSERT INTO `kpi_process_reviews` VALUES (1,'REV-2026-Q3','Q3 2026 Clinical Sourcing & Hospital Pharmacy Supply Chain Review','2026-07-01','2026-09-30',150002,'approved',1,'2026-09-19 16:35:01',NULL,'Quarterly multi-department review assessing DOH Drug Price Reference Index (DPRI) price ceilings, critical antibiotic batch replenishment, cold chain compliance, and hospital inventory shrinkage.','Procurement realized ₱42,500 savings under DPRI ceilings across essential anti-infectives and analgesics. Inventory shrinkage was maintained below the 0.35% hospital tolerance threshold.','{\"aggregate_savings_pct\": 3.4, \"avg_supplier_score\": 84.4, \"bottleneck_stages\": {\"stage_1_pr_approval\": {\"max_tat_days\": 9.85, \"mean_tat_days\": 3.71, \"min_tat_days\": 1, \"name\": \"PR Creation to Approval\", \"sample_count\": 8, \"sla_breach_rate\": 37.5, \"sla_target_days\": 3, \"status\": \"elevated\", \"variance_sigma\": 2.93}, \"stage_2_sourcing_award\": {\"max_tat_days\": 8, \"mean_tat_days\": 5.5, \"min_tat_days\": 3, \"name\": \"Sourcing RFQ to Award\", \"sample_count\": 6, \"sla_breach_rate\": 16.67, \"sla_target_days\": 7, \"status\": \"healthy\", \"variance_sigma\": 1.71}, \"stage_3_po_conforme\": {\"max_tat_days\": 4, \"mean_tat_days\": 1.65, \"min_tat_days\": 0.1, \"name\": \"PO Issuance to Conforme\", \"sample_count\": 8, \"sla_breach_rate\": 25, \"sla_target_days\": 2, \"status\": \"healthy\", \"variance_sigma\": 1.29}, \"stage_4_vendor_lead_time\": {\"max_tat_days\": 15, \"mean_tat_days\": 5.74, \"min_tat_days\": 0.1, \"name\": \"Dispatch to Gate Arrival (Lead Time)\", \"sample_count\": 33, \"sla_breach_rate\": 15.15, \"sla_target_days\": 10, \"status\": \"elevated\", \"variance_sigma\": 3.65}, \"stage_5_technical_inspection\": {\"max_tat_days\": 2, \"mean_tat_days\": 0.9, \"min_tat_days\": 0.1, \"name\": \"Receiving to Technical Inspection\", \"sample_count\": 7, \"sla_breach_rate\": 28.57, \"sla_target_days\": 1, \"status\": \"healthy\", \"variance_sigma\": 0.79}, \"stage_6_custodial_acceptance\": {\"max_tat_days\": 2, \"mean_tat_days\": 1.01, \"min_tat_days\": 0.1, \"name\": \"Inspection to Custodial Acceptance\", \"sample_count\": 7, \"sla_breach_rate\": 14.29, \"sla_target_days\": 1, \"status\": \"elevated\", \"variance_sigma\": 0.51}}, \"ceiling_breaches_count\": 0, \"critical_bottleneck\": {\"key\": \"stage_1_pr_approval\", \"mean_tat_days\": 3.71, \"name\": \"PR Creation to Approval\", \"sla_target_days\": 3, \"variance_sigma\": 2.93}, \"dpri_compliance_pct\": 98.4, \"fill_rate_pct\": 94.8, \"net_savings_amount\": 42500, \"on_time_delivery_pct\": 92.1, \"overall_stock_accuracy\": 99.6, \"suppliers_evaluated\": 14, \"total_spend\": 1250000, \"total_spend_evaluated\": 1250000}','2026-09-13 20:06:20','2026-09-24 16:35:35'),(2,'REV-2026-Q4','Q4 2026 Pre-Audit Sourcing & Inventory Shrinkage Governance Review','2026-10-01','2026-12-31',150002,'submitted',NULL,NULL,NULL,'Preliminary pre-audit review focused on surgical consignment supplies, cold chain IoT monitoring, and vendor accreditation renewals.','Identified 3 active suppliers requiring license to operate renewal and 2 cold storage zones needing telemetry sensor recalibration. Preliminary Q4 procurement realized ₱18,500 savings under DPRI ceilings.','{\"aggregate_savings_pct\": 4.1, \"avg_supplier_score\": 89.5, \"bottleneck_stages\": {\"stage_1_pr_approval\": {\"max_tat_days\": 4, \"mean_tat_days\": 2.17, \"min_tat_days\": 1, \"name\": \"PR Creation to Approval\", \"sample_count\": 6, \"sla_breach_rate\": 16.67, \"sla_target_days\": 3, \"status\": \"healthy\", \"variance_sigma\": 1.07}, \"stage_2_sourcing_award\": {\"max_tat_days\": 8, \"mean_tat_days\": 5.5, \"min_tat_days\": 3, \"name\": \"Sourcing RFQ to Award\", \"sample_count\": 6, \"sla_breach_rate\": 16.67, \"sla_target_days\": 7, \"status\": \"healthy\", \"variance_sigma\": 1.71}, \"stage_3_po_conforme\": {\"max_tat_days\": 4, \"mean_tat_days\": 2.17, \"min_tat_days\": 1, \"name\": \"PO Issuance to Conforme\", \"sample_count\": 6, \"sla_breach_rate\": 33.33, \"sla_target_days\": 2, \"status\": \"elevated\", \"variance_sigma\": 1.07}, \"stage_4_vendor_lead_time\": {\"max_tat_days\": 13, \"mean_tat_days\": 7.83, \"min_tat_days\": 4, \"name\": \"Dispatch to Gate Arrival (Lead Time)\", \"sample_count\": 6, \"sla_breach_rate\": 33.33, \"sla_target_days\": 10, \"status\": \"elevated\", \"variance_sigma\": 3.24}, \"stage_5_technical_inspection\": {\"max_tat_days\": 2, \"mean_tat_days\": 1.03, \"min_tat_days\": 0.1, \"name\": \"Receiving to Technical Inspection\", \"sample_count\": 6, \"sla_breach_rate\": 33.33, \"sla_target_days\": 1, \"status\": \"elevated\", \"variance_sigma\": 0.78}, \"stage_6_custodial_acceptance\": {\"max_tat_days\": 2, \"mean_tat_days\": 1.02, \"min_tat_days\": 0.1, \"name\": \"Inspection to Custodial Acceptance\", \"sample_count\": 6, \"sla_breach_rate\": 16.67, \"sla_target_days\": 1, \"status\": \"elevated\", \"variance_sigma\": 0.55}}, \"ceiling_breaches_count\": 0, \"critical_bottleneck\": {\"key\": \"stage_3_po_conforme\", \"mean_tat_days\": 2.17, \"name\": \"PO Issuance to Conforme\", \"sla_target_days\": 2, \"variance_sigma\": 1.07}, \"dpri_compliance_pct\": 96, \"fill_rate_pct\": 91.5, \"net_savings_amount\": 18500, \"on_time_delivery_pct\": 89, \"overall_stock_accuracy\": 98.8, \"suppliers_evaluated\": 12, \"total_spend\": 450000, \"total_spend_evaluated\": 450000}','2026-09-13 20:06:20','2026-09-24 16:35:39');
